export default function UserComment({ commentText, rawHtml }) {
  return (
    <div>
      {/* 
        ✅ SAFE BY DEFAULT. 
        If commentText contains <script>alert('Hacked')</script>, 
        React turns it into plain text. It will NOT run.
      */}
      <p>{commentText}</p>

      {/* 
        ❌ EXTREMELY DANGEROUS. 
        This explicitly tells React to execute whatever is in rawHtml as code.
        Only use this if you ran DOMPurify on rawHtml first!
      */}
      <div dangerouslySetInnerHTML={{ __html: rawHtml }} />
    </div>
  );
}
